export const getExercisesByPath = (level, skill, difficulty, levelNum) => {
  let data;
  if (level === 'a1') {
    data = A1_USE_OF_ENGLISH[difficulty]?.[`level${levelNum}`] || [];
  } else if (level === 'a2') {
    data = A2_USE_OF_ENGLISH[difficulty]?.[`level${levelNum}`] || [];
  } else if (level === 'b1') {
    data = B1_USE_OF_ENGLISH[difficulty]?.[`level${levelNum}`] || [];
  } else if (level === 'b2') {
    data = B2_USE_OF_ENGLISH[difficulty]?.[`level${levelNum}`] || [];
  } else if (level === 'c1') {
    data = C1_USE_OF_ENGLISH[difficulty]?.[`level${levelNum}`] || [];
  } else if (level === 'c2') {
    data = C2_USE_OF_ENGLISH[difficulty]?.[`level${levelNum}`] || [];
  } else {
    data = [];
  }
  return data;
};
